306				char c = s.charAt(i);
307				if (c < '0' || c > '9') {
308					continue;
309				}
310				int d = c - '0';
311				if (dbl) {
312					d *= 2;
313					if (d > 9) {
314						d -= 9;
315					}
316				}
317				sum += d;
318				dbl = !dbl;
319			}
320			return (10 - (sum % 10)) % 10;
